import { billingPeriodEnd } from "@/lib/billing";
import { parseIso } from "@/lib/date";
import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { fullPeriodCharge, publishInvoice } from "@/server/services/billing-service";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "./types";

const logger = createLogger("billing-renewal-job");

export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    const stamp = toIsoTimestamp(now);
    const due = await subscriptionRepo.listSubscriptionsDueForRenewal(stamp);

    for (let subscription of due) {
      try {
        let processed = false;
        if (subscription.status === "canceled" && subscription.cancelAt !== null) {
          const change = subscriptionRepo.applyBillingChange(subscription, {
            plan: "free",
            interval: "monthly",
            status: "active",
            cancelAt: null,
            currentPeriodStart: subscription.cancelAt,
            currentPeriodEnd: billingPeriodEnd(subscription.cancelAt, "monthly"),
          }, 0, now);
          if (!change) continue;
          await emit("billing.plan_changed", {
            orgId: subscription.orgId,
            actorId: null,
            occurredAt: stamp,
            from: subscription.plan,
            to: "free",
          });
          subscription = change.subscription;
          processed = true;
        }

        while (subscription.status === "active" &&
          parseIso(subscription.currentPeriodEnd).getTime() <= now.getTime()) {
          const start = subscription.currentPeriodEnd;
          const change = subscriptionRepo.applyBillingChange(subscription, {
            currentPeriodStart: start,
            currentPeriodEnd: billingPeriodEnd(start, subscription.interval),
          }, fullPeriodCharge(subscription), now);
          if (!change) break;
          subscription = change.subscription;
          if (change.invoice) await publishInvoice(change.invoice, null, now);
          processed = true;
        }
        if (processed) result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("billing renewal failed", {
          orgId: subscription.orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}
/**
 * Subscription rows; one active row per organization.
 */
import { and, eq, isNotNull, isNull, lte, ne, or } from "drizzle-orm";
import { billingPeriodEnd } from "@/lib/billing";
import { newId } from "@/lib/id";
import { getDb, organizations, subscriptions } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toSubscription } from "./_mappers";
import { insertIssuedInvoice } from "./invoice-repository";
import type { BillingInterval, Invoice, PlanId, Subscription } from "@/types/billing";
import type { IsoTimestamp, OrgId } from "@/types/common";

const MS_PER_DAY = 24 * 60 * 60 * 1000;
const TRIAL_DAYS = 14;

export async function findSubscription(
  orgId: OrgId,
): Promise<Subscription | null> {
  const row = getDb()
    .select()
    .from(subscriptions)
    .where(orgPredicate(subscriptions.orgId, orgId))
    .get();
  return row ? toSubscription(row) : null;
}

/** New organizations start on a trial period rather than an active plan. */
export async function insertSubscription(
  orgId: OrgId,
  plan: PlanId,
  interval: BillingInterval,
): Promise<Subscription> {
  const now = new Date();
  const stamp = toIsoTimestamp(now);
  const periodEnd = plan === "free"
    ? billingPeriodEnd(stamp, interval)
    : toIsoTimestamp(new Date(now.getTime() + TRIAL_DAYS * MS_PER_DAY));

  const row = getDb()
    .insert(subscriptions)
    .values({
      id: newId(),
      orgId,
      plan,
      interval,
      status: plan === "free" ? "active" : "trialing",
      seats: 1,
      currentPeriodStart: stamp,
      currentPeriodEnd: periodEnd,
      cancelAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toSubscription(row);
}

/** Activates a plan, including the trial-expiry job's fallback to free. */
export async function updateSubscriptionPlan(
  orgId: OrgId,
  plan: PlanId,
  interval: BillingInterval,
): Promise<Subscription> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .update(subscriptions)
    .set({ plan, interval, status: "active", updatedAt: stamp })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

export async function updateSeatCount(
  orgId: OrgId,
  seats: number,
): Promise<Subscription> {
  const row = getDb()
    .update(subscriptions)
    .set({ seats, updatedAt: toIsoTimestamp(new Date()) })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

/** `cancelAt === null` reactivates a subscription scheduled for cancellation. */
export async function cancelSubscription(
  orgId: OrgId,
  cancelAt: IsoTimestamp | null,
): Promise<Subscription> {
  const row = getDb()
    .update(subscriptions)
    .set({
      cancelAt,
      status: cancelAt === null ? "active" : "canceled",
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

/** Feeds the trial-expiry job; cross-tenant by design, it sweeps every org. */
export async function listTrialsEndingBefore(
  before: IsoTimestamp,
): Promise<readonly Subscription[]> {
  const rows = getDb()
    .select()
    .from(subscriptions)
    .where(
      and(
        eq(subscriptions.status, "trialing"),
        isNotNull(subscriptions.currentPeriodEnd),
        lte(subscriptions.currentPeriodEnd, before),
        ne(subscriptions.plan, "free"),
      ),
    )
    .all();

  return rows.map(toSubscription);
}

/** Cross-tenant sweep without a batch ceiling; archived workspaces are excluded. */
export async function listSubscriptionsDueForRenewal(
  now: IsoTimestamp,
): Promise<readonly Subscription[]> {
  const rows = getDb()
    .select({ subscription: subscriptions })
    .from(subscriptions)
    .innerJoin(organizations, eq(organizations.id, subscriptions.orgId))
    .where(and(
      isNull(organizations.archivedAt),
      or(
        and(eq(subscriptions.status, "active"), lte(subscriptions.currentPeriodEnd, now)),
        and(eq(subscriptions.status, "canceled"), lte(subscriptions.cancelAt, now)),
      ),
    ))
    .all();
  return rows.map(({ subscription }) => toSubscription(subscription));
}

type BillingPatch = Partial<Pick<Subscription,
  "plan" | "interval" | "status" | "seats" | "currentPeriodStart" | "currentPeriodEnd" | "cancelAt"
>>;

/** A stale snapshot cannot advance or charge the same subscription twice. */
export function applyBillingChange(
  current: Subscription,
  patch: BillingPatch,
  amountCents: number,
  now: Date,
): { subscription: Subscription; invoice: Invoice | null } | null {
  const stamp = toIsoTimestamp(now);
  return getDb().transaction((tx) => {
    const row = tx.update(subscriptions)
      .set({ ...patch, updatedAt: stamp })
      .where(and(
        orgPredicate(subscriptions.orgId, current.orgId),
        eq(subscriptions.id, current.id),
        eq(subscriptions.plan, current.plan),
        eq(subscriptions.interval, current.interval),
        eq(subscriptions.status, current.status),
        eq(subscriptions.seats, current.seats),
        eq(subscriptions.currentPeriodStart, current.currentPeriodStart),
        eq(subscriptions.currentPeriodEnd, current.currentPeriodEnd),
        current.cancelAt === null
          ? isNull(subscriptions.cancelAt)
          : eq(subscriptions.cancelAt, current.cancelAt),
      ))
      .returning().get();
    if (!row) return null;

    if (patch.plan !== undefined) {
      tx.update(organizations).set({ plan: patch.plan, updatedAt: stamp })
        .where(eq(organizations.id, current.orgId)).run();
    }

    const subscription = toSubscription(row);
    const invoice = amountCents > 0
      ? insertIssuedInvoice(tx, current.orgId, amountCents,
        subscription.currentPeriodStart, subscription.currentPeriodEnd, stamp)
      : null;
    return { subscription, invoice };
  });
}

